package com.example.starter.consent;

/**
 * 委托状态：有效（ACTIVE）或已撤销（REVOKED），只允许从有效变为已撤销。
 */
public enum DelegateStatus {
    ACTIVE,
    REVOKED
}

package com.example.starter.consent;

/**
 * 批量操作中的单条拒绝原因：target 为主体标识或委托指纹，reason 为稳定原因码。
 *
 * @param target 被拒绝的对象标识（主体标识或委托指纹）
 * @param reason 稳定原因码，如 DELEGATION_VERSION_CONFLICT、DELEGATION_EXPIRED
 */
public record RejectionReason(String target, String reason) {
}

package com.example.starter.consent;

import java.util.List;

import org.springframework.http.HttpStatus;

/**
 * 批量拒绝异常：携带稳定业务码、HTTP 状态与逐对象拒绝原因，
 * 由全局异常处理器转换为带 reasons 列表的错误响应，整批不生效。
 */
public class BatchRejectionException extends RuntimeException {

    private final HttpStatus status;
    private final String code;
    private final List<RejectionReason> reasons;

    public BatchRejectionException(HttpStatus status, String code, String message, List<RejectionReason> reasons) {
        super(message);
        this.status = status;
        this.code = code;
        this.reasons = List.copyOf(reasons);
    }

    public HttpStatus getStatus() {
        return status;
    }

    public String getCode() {
        return code;
    }

    public List<RejectionReason> getReasons() {
        return reasons;
    }
}

package com.example.starter.consent;

import java.util.List;

/**
 * 批量拒绝错误响应体：code 为稳定业务码，reasons 逐对象列出拒绝原因。
 *
 * @param code    稳定业务码
 * @param message 可读描述
 * @param reasons 逐对象拒绝原因列表
 */
public record BatchErrorResponse(String code, String message, List<RejectionReason> reasons) {
}

package com.example.starter.consent;

import java.util.concurrent.locks.ReentrantLock;

import org.springframework.stereotype.Component;

/**
 * 授权域串行裁决锁：委托、续签、撤销、用途迁移（授权/撤回）与批量查询
 * 在同一 JVM 内按提交顺序裁决，避免跨操作交错产生不一致判定。
 */
@Component
public class ConsentLock {

    private final ReentrantLock lock = new ReentrantLock(true);

    public void lock() {
        lock.lock();
    }

    public void unlock() {
        lock.unlock();
    }
}

package com.example.starter.consent;

import java.time.Clock;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * 时间源配置：委托 UTC 有效期判定统一使用注入的 Clock，测试中可替换为可控时钟。
 */
@Configuration
public class TimeConfig {

    @Bean
    public Clock clock() {
        return Clock.systemUTC();
    }
}

