import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * 委托创建请求：主体为代理人授予用途范围委托。
 * delegateKey 由主体、代理、授权代次、规范化用途、UTC 区间与版本指纹生成，同键重放返回原委托。
 *
 * @param subjectKey      主体标识（合成字符串）
 * @param delegateId      代理人标识，不得与主体相同（否则 422）
 * @param purposes        用途集合，规范化（去重升序）后为空返回 422
 * @param validFrom       UTC 有效期起点（含），ISO-8601
 * @param validTo         UTC 有效期终点（不含），ISO-8601；必须晚于起点
 * @param delegateVersion 委托版本，从 1 开始
 */
public record DelegateCreateRequest(
        @NotBlank @Size(max = 128) String subjectKey,
        @NotBlank @Size(max = 128) String delegateId,
        @NotNull Set<Purpose> purposes,
        @NotNull Instant validFrom,
        @NotNull Instant validTo,
        @Min(1) int delegateVersion) {
}

package com.example.starter.consent.dto;

import java.time.Instant;
import java.util.List;
import java.util.Map;

import com.example.starter.consent.DelegateStatus;
import com.example.starter.consent.Purpose;

/**
 * 委托响应：返回委托指纹、主体、代理、规范化用途、各用途授权代次、UTC 区间、版本与状态。
 *
 * @param delegateKey     委托指纹（SHA-256）
 * @param subjectKey      主体标识
 * @param delegateId      代理人标识
 * @param purposes        规范化用途集合（升序）
 * @param epochs          创建时各用途授权代次（用途 → 代次）
 * @param validFrom       UTC 有效期起点（含）
 * @param validTo         UTC 有效期终点（不含）
 * @param delegateVersion 委托版本
 * @param status          状态：ACTIVE 有效 / REVOKED 已撤销
 */
public record DelegateResponse(
        String delegateKey,
        String subjectKey,
        String delegateId,
        List<Purpose> purposes,
        Map<Purpose, Integer> epochs,
        Instant validFrom,
        Instant validTo,
        int delegateVersion,
        DelegateStatus status) {
}

package com.example.starter.consent.dto;

import java.time.Instant;
import java.util.List;

import jakarta.validation.Valid;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * 批量续签请求：先校验每份旧委托版本，任一冲突整批不生效（409 并逐条列出原因）。
 *
 * @param requestId 幂等请求标识
 * @param items     续签项列表，至少一条
 */
public record DelegateRenewRequest(
        @NotBlank @Size(max = 128) String requestId,
        @NotEmpty List<@Valid RenewItem> items) {

    /**
     * 单条续签项：按旧委托指纹定位，校验版本后生成版本递增、区间更新的新委托。
     *
     * @param delegateKey     旧委托指纹
     * @param expectedVersion 期望的旧委托当前版本，不一致则整批冲突
     * @param validFrom       新 UTC 有效期起点（含）
     * @param validTo         新 UTC 有效期终点（不含），必须晚于起点
     */
    public record RenewItem(
            @NotBlank @Size(max = 64) String delegateKey,
            @Min(1) int expectedVersion,
            @NotNull Instant validFrom,
            @NotNull Instant validTo) {
    }
}

package com.example.starter.consent.dto;

import java.util.List;

/**
 * 批量续签响应：逐条返回旧委托指纹、新委托指纹与新版本。
 *
 * @param items 续签结果列表
 */
public record DelegateRenewResponse(List<RenewedItem> items) {

    /**
     * 单条续签结果。
     *
     * @param oldDelegateKey  旧委托指纹（已随续签撤销）
     * @param newDelegateKey  新委托指纹
     * @param delegateVersion 新委托版本（旧版本 + 1）
     */
    public record RenewedItem(String oldDelegateKey, String newDelegateKey, int delegateVersion) {
    }
}

package com.example.starter.consent.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

/**
 * 委托撤销请求：撤销只影响后续查询，已生成的查询快照不受影响。
 *
