        assertThat(replay.getResponse().getStatus()).isEqualTo(200);
        assertThat(count("SELECT COUNT(*) FROM delegate_query")).isEqualTo(1);
        assertThat(count("SELECT COUNT(*) FROM delegate_query_item")).isEqualTo(1);
    }

